// Package agent drives Claude Code (the claude CLI) for a fix attempt: it
// launches it headless in Michel's work copy, in stream-json mode, with a
// closed argv, an allowlisted environment, settings and an MCP
// configuration generated by Michel, and none of the user's or the
// project's own Claude Code settings, hooks, plugins, memory or MCP
// servers. What Claude Code writes is untrusted data: every line becomes an
// Event with sanitized text, never an instruction for Michel.
package agent

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"regexp"
	"strings"
	"time"

	"github.com/kvarot/michel/internal/i18n"
	"github.com/kvarot/michel/internal/scan"
	"github.com/kvarot/michel/internal/workcopy"
)

// EnvBinary names the claude binary to run when Deps.Binary is empty
// (controller ruling 3); without it, claude is looked up on the PATH.
const EnvBinary = "MICHEL_CLAUDE_BIN"

// Deps are the collaborators of the agent driver.
type Deps struct {
	// Binary is the claude CLI. Empty means $MICHEL_CLAUDE_BIN, else
	// claude on the PATH.
	Binary string
	// Exec runs the short commands of Detect (--version, --help, auth
	// status). Nil means workcopy.DefaultExec. Start runs Claude Code
	// itself, with pipes.
	Exec workcopy.ExecFunc
	// DataDir is Michel's data folder: the copies are in
	// <DataDir>/worktrees, the generated files in <DataDir>/fix-home.
	DataDir string
	// ProxyAddr is the allow proxy of purpose agent.claude (the URL
	// allowproxy.Listen returns, token included): only in the environment,
	// never in argv, errors or events.
	ProxyAddr string
	// Now is the clock. Nil means time.Now.
	Now func() time.Time
	// Home is the user's profile folder, where Claude Code keeps the
	// user's login (.claude/.credentials.json, .claude.json). Empty means
	// os.UserHomeDir. Tests point it at a temporary folder.
	Home string
}

func (d Deps) binary() string {
	if d.Binary != "" {
		return d.Binary
	}
	if b := os.Getenv(EnvBinary); b != "" {
		return b
	}
	return "claude"
}

func (d Deps) exec() workcopy.ExecFunc {
	if d.Exec != nil {
		return d.Exec
	}
	return workcopy.DefaultExec
}

func (d Deps) home() (string, error) {
	if d.Home != "" {
		return d.Home, nil
	}
	return os.UserHomeDir()
}

func (d Deps) workcopy() workcopy.Deps {
	return workcopy.Deps{DataDir: d.DataDir, Exec: d.Exec, ProxyAddr: d.ProxyAddr, Now: d.Now}
}

// The hints of Status, catalog keys (Status.Message translates them).
const (
	HintNotInstalled = "agent.hint.not_installed"
	HintNotLoggedIn  = "agent.hint.not_logged_in"
	HintTooOld       = "agent.hint.too_old"
	HintEnv          = "agent.hint.env"  // Michel could not build Claude Code's environment
	HintSlow         = "agent.hint.slow" // Claude Code did not answer in time: nothing is known of it
)

// Status is what Michel knows of the installed Claude Code.
type Status struct {
	Installed bool
	Version   string
	LoggedIn  bool
	// Hint is the catalog key of what the user should do, "" when Claude
	// Code can be used.
	Hint string
}

// Message is the hint in lang, "" when there is none.
func (s Status) Message(lang i18n.Lang) string {
	switch s.Hint {
	case HintNotInstalled:
		return i18n.T(lang, "agent.hint.not_installed")
	case HintNotLoggedIn:
		return i18n.T(lang, "agent.hint.not_logged_in")
	case HintTooOld:
		return i18n.T(lang, "agent.hint.too_old")
	case HintEnv:
		return i18n.T(lang, "agent.hint.env")
	case HintSlow:
		return i18n.T(lang, "agent.hint.slow")
	}
	return ""
}

// Errors of Start before Claude Code runs.
var (
	ErrNotInstalled = errors.New("Claude Code is not installed")
	ErrTooOld       = errors.New("this version of Claude Code cannot be run isolated from the user's settings")
	errSlow         = errors.New("Claude Code did not answer in time")
)

// isolationFlags are the options of `claude --help` Michel's launch needs.
// Without --setting-sources, --strict-mcp-config or --restricted, the
// user's or the project's settings, hooks and MCP servers would load: such
// a version is refused. --max-turns is a hidden option (not in --help) of
// the versions that have the others.
var isolationFlags = []string{"--print", "--input-format", "--output-format", "--verbose", "--mcp-config", "--strict-mcp-config",
	"--settings", "--setting-sources", "--restricted", "--tools", "--permission-mode", "--permission-prompts",
	"--allowedTools", "--disallowedTools", "--resume", "--disable-slash-commands", `"dontAsk"`}

// versionLine is the first line of `claude --version`: 2.1.314 (Claude Code).
var versionLine = regexp.MustCompile(`^([0-9]+\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.]+)?)\b`)

// detectTimeout bounds each command of Detect.
const detectTimeout = 30 * time.Second

// Detect reports whether Claude Code is installed (claude --version), has
// the isolation options (claude --help) and is logged in (claude auth status
// --json, the documented status command: it reads the user's login, sends
// no prompt). Nothing of the answers but the version and loggedIn is kept.
// When the environment of Claude Code cannot be built (data folder or user
// profile missing), the hint is HintEnv and nothing runs. auth status takes
// no --setting-sources (its help lists --json and --text only), so it runs
// with Claude Code's default sources; it only reads the login.
func Detect(ctx context.Context, d Deps) Status {
	st := Status{}
	if _, err := environment(d); err != nil {
		st.Hint = HintEnv
		return st
	}
	version, err := installed(ctx, d)
	if err != nil {
		st.Hint = HintNotInstalled
		return st
	}
	st.Installed, st.Version = true, version
	if err := isolated(ctx, d); err != nil {
		st.Hint = HintTooOld
		if errors.Is(err, errSlow) {
			st.Hint = HintSlow
		}
		return st
	}
	env, err := environment(d)
	if err != nil {
		st.Hint = HintEnv
		return st
	}
	cctx, cancel := context.WithTimeout(ctx, detectTimeout)
	defer cancel()
	out, _, err := d.exec()(cctx, d.binary(), []string{"auth", "status", "--json"}, env, d.DataDir)
	var auth struct {
		LoggedIn bool `json:"loggedIn"`
	}
	if err != nil || json.Unmarshal(out, &auth) != nil || !auth.LoggedIn {
		st.Hint = HintNotLoggedIn
		return st
	}
	st.LoggedIn = true
	return st
}

// installed runs claude --version and returns the version.
func installed(ctx context.Context, d Deps) (string, error) {
	env, err := environment(d)
	if err != nil {
		return "", err
	}
	cctx, cancel := context.WithTimeout(ctx, detectTimeout)
	defer cancel()
	out, _, err := d.exec()(cctx, d.binary(), []string{"--version"}, env, d.DataDir)
	if err != nil {
		return "", ErrNotInstalled
	}
	line, _, _ := strings.Cut(strings.TrimSpace(string(out)), "\n")
	m := versionLine.FindStringSubmatch(strings.TrimSpace(line))
	if m == nil {
		return "", ErrNotInstalled
	}
	return scan.SanitizeText(m[1]), nil
}

// isolated checks that claude --help lists every option of isolationFlags.
func isolated(ctx context.Context, d Deps) error {
	env, err := environment(d)
	if err != nil {
		return err
	}
	cctx, cancel := context.WithTimeout(ctx, detectTimeout)
	defer cancel()
	out, _, err := d.exec()(cctx, d.binary(), []string{"--help"}, env, d.DataDir)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) || cctx.Err() != nil {
			return errSlow
		}
		return ErrTooOld
	}
	help := string(out)
	for _, f := range isolationFlags {
		if !hasOption(help, f) {
			return ErrTooOld
		}
	}
	return nil
}

// hasOption reports whether the help text names the option f as a whole
// word (--settings is not found in --setting-sources).
func hasOption(help, f string) bool {
	for i := 0; ; {
		j := strings.Index(help[i:], f)
		if j < 0 {
			return false
		}
		end := i + j + len(f)
		if end == len(help) || !isOptionChar(help[end]) {
			return true
		}
		i = end
	}
}

func isOptionChar(c byte) bool {
	return c == '-' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9'
}
